-- Tejas Jhaveri's LinkedIn client metrics, Sep 2024 - Jun 2025: CEO scorecard vs the app, week by week. Read-only.
with series(metric, pts) as (values
  ('C01','24-09-09:16 24-10-07:2 24-10-14:20 24-10-21:20 24-11-11:44 24-11-18:16 24-12-09:20 24-12-30:5 25-01-06:6 25-01-13:36 25-02-17:17 25-04-14:6 25-06-30:2'),
  ('C03','24-09-09:16 24-10-07:6 24-10-14:12 24-10-21:12 24-10-28:1 24-11-11:17 24-11-18:16 24-11-25:8 24-12-09:24 24-12-30:5 25-01-06:3 25-01-13:10 25-02-03:1 25-02-17:36 25-03-03:1 25-03-10:4 25-04-14:3 25-06-09:1 25-06-30:2'),
  ('C06','24-11-25:5 24-12-02:2 24-12-09:14 24-12-30:4 25-01-06:1 25-01-13:18 25-01-27:5 25-02-03:6 25-02-17:18 25-02-24:4 25-03-03:3 25-03-10:7 25-03-31:3 25-04-07:4 25-04-14:1 25-04-28:3 25-05-05:3 25-05-12:1 25-05-26:5 25-06-02:2'),
  ('C10','24-08-26:658 24-09-09:4000 24-09-16:3286 24-09-30:509 24-10-07:166 24-10-14:2738 24-10-21:4000 24-10-28:6295 24-11-04:1088 24-11-11:16118 24-11-18:4000 24-11-25:4095 24-12-02:91250 24-12-09:16423 24-12-30:2304 25-01-06:1472 25-01-13:4770 25-01-27:428 25-02-03:2773 25-02-24:865 25-03-03:717 25-03-10:997 25-03-31:409 25-04-07:654 25-04-14:675 25-04-28:176 25-05-05:525 25-05-12:381 25-05-26:467 25-06-02:308 25-06-09:278 25-06-30:2092'),
  ('C13','24-09-30:51 24-10-07:30 24-10-14:244 24-10-28:132 24-11-04:6 24-11-11:246 24-11-18:300 24-11-25:17 24-12-02:61 24-12-09:126 24-12-30:118 25-01-06:107 25-01-13:915 25-01-27:75 25-02-03:288 25-02-17:915'),
  ('C14','24-12-09:128 25-01-27:47 25-02-17:4770 25-02-24:64 25-03-03:32 25-03-10:43 25-04-07:15 25-05-05:94 25-05-26:88 25-06-02:81 25-06-09:104 25-06-30:95'),
  ('C15','24-11-25:54 24-12-09:301 25-04-28:54 25-05-05:74 25-05-12:103 25-05-26:114 25-06-02:48 25-06-09:102 25-06-30:83'),
  ('C17','24-09-02:268 24-09-09:500 24-09-30:101 24-10-07:26 24-10-14:416 24-10-21:500 24-10-28:149 24-11-11:314 24-11-18:500 24-11-25:76 24-12-09:459 24-12-30:84 25-01-06:74 25-01-13:428 25-01-27:115 25-02-03:105 25-02-17:428 25-02-24:74 25-03-03:51 25-03-10:125 25-03-31:36 25-04-07:33 25-04-14:85 25-04-28:21 25-05-05:160 25-05-12:109 25-05-26:75 25-06-02:75 25-06-09:113 25-06-30:61'),
  ('L10','25-04-07:284'),
  ('L11','25-04-07:67 25-04-14:128 25-04-28:44 25-05-05:73 25-05-12:31 25-05-26:59 25-06-02:68 25-06-09:79'),
  ('L12','25-04-07:23.6 25-04-14:46.9 25-04-28:65.67 25-05-05:36.5 25-05-12:50.82 25-05-26:29.5 25-06-02:34.17 25-06-09:44.38'),
  ('L13','25-04-07:11 25-05-26:28 25-06-02:34 25-06-09:39'),
  ('L16','25-05-05:9 25-05-26:10 25-06-02:15 25-06-09:20'),
  ('L20','25-04-14:0.52 25-04-28:7 25-05-05:34 25-05-12:12')
),
sheet as (
  select s.metric, ('20' || split_part(p, ':', 1))::date as week_start, split_part(p, ':', 2)::numeric as sheet_value
  from series s cross join lateral regexp_split_to_table(s.pts, ' ') as p
),
app as (
  select e.key as metric, w.week_start,
         case when jsonb_typeof(e.value) = 'object' then e.value->>'value' else e.value #>> '{}' end as r
  from myntmore.weekly_data w
  join myntmore.clients c on c.id = w.client_id and lower(c.name) like '%tejas%'
  cross join lateral (select * from jsonb_each(case when jsonb_typeof(w.content_metrics) = 'object' then w.content_metrics else '{}'::jsonb end) union all select * from jsonb_each(case when jsonb_typeof(w.leadgen_metrics) = 'object' then w.leadgen_metrics else '{}'::jsonb end)) e
)
select s.metric, s.week_start, s.sheet_value,
       case when a.r ~ '^-?[0-9]+(\.[0-9]+)?$' then a.r::numeric end as app_value
from sheet s
left join app a on a.metric = s.metric and a.week_start = s.week_start
where a.r is null or not (a.r ~ '^-?[0-9]+(\.[0-9]+)?$') or abs(a.r::numeric - s.sheet_value) > 0.5
order by s.metric, s.week_start;
